import { Brush } from '@visx/brush';
import BaseBrush from '@visx/brush/lib/BaseBrush';
import { Bounds, Point, Scale } from '@visx/brush/lib/types';
import { PickD3Scale } from '@visx/scale';
import React, { useRef, useState } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { VerticalCrosshair } from '../crosshair/VerticalCrosshair.js';
import { BRUSH_STYLES } from '../overlays/constants.js';

export const BRUSH_HIDDEN_STYLES = {
  fill: 'transparent',
  stroke: 'transparent',
  opacity: 1,
};

//Min px to perfome a brush drag
const MIN_DRAG_PX = 10;

export interface ZoomBrushProps {
  width: number;
  height: number;
  yScale: Scale;
  xScale: PickD3Scale<'linear' | 'log', number>;
  onBrushChange: () => void;
  onBrushEnd: (domain: Bounds) => void;
  labelAccessor: (position: number) => string;
}

export function ZoomBrush({
  width,
  height,
  yScale,
  xScale,
  onBrushEnd,
  onBrushChange,
  labelAccessor,
}: ZoomBrushProps) {
  const [brushStart, setBrushStart] = useState<number | null>(null);
  const [brushEnd, setBrushEnd] = useState<number | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  const innerBrushRef = useRef<BaseBrush | null>(null);

  const handleBrushStart = (point: Point) => {
    setBrushStart(point.x ?? 0);
  };

  const handleBrushChange = (domain: Bounds | null) => {
    if (!domain) {
      return;
    }

    const startCoordinate = xScale(domain.x0) ?? 0;
    const endCoordinate = xScale(domain.x1) ?? 0;
    const brushStartCoordinate = xScale(brushStart ?? 0) ?? 0;

    const hasMinSpaceToDrag =
      brushEnd || Math.abs(startCoordinate - endCoordinate) > MIN_DRAG_PX;

    if (hasMinSpaceToDrag && startCoordinate) {
      onBrushChange();

      const start = Math.round(startCoordinate);
      const startBrush = Math.round(brushStartCoordinate - 2);
      const brushingLeft = start < startBrush;

      setBrushEnd(
        xScale.invert(brushingLeft ? startCoordinate : endCoordinate),
      );
      setIsDragging(true);
    }
  };

  const handleBrushEnd = (domain: Bounds | null) => {
    setBrushEnd(null);
    setBrushStart(null);

    if (!domain || !isDragging) {
      return;
    }

    onBrushEnd(domain);
    setIsDragging(false);
  };

  const showCrosshair = isDragging && brushEnd !== null;

  return (
    <>
      <Brush
        disableDraggingSelection={true}
        xScale={xScale}
        yScale={yScale}
        width={width}
        height={height}
        handleSize={8}
        innerRef={innerBrushRef}
        resizeTriggerAreas={['left', 'right']}
        brushDirection="horizontal"
        onChange={handleBrushChange}
        onBrushStart={handleBrushStart}
        onBrushEnd={handleBrushEnd}
        selectedBoxStyle={isDragging ? BRUSH_STYLES : BRUSH_HIDDEN_STYLES}
        resetOnEnd
      />
      {showCrosshair && (
        <VerticalCrosshair
          data-testid="vertical-crosshair-brush-end"
          x={xScale(brushStart ?? 0) ?? 0}
          label={labelAccessor(brushStart ?? 0)}
          height={height}
          dashed={false}
          color={Colors.Background.Field.Primary.Accent}
          focusable
        />
      )}
      {showCrosshair && (
        <VerticalCrosshair
          data-testid="vertical-crosshair-brush-start"
          x={xScale(brushEnd ?? 0) ?? 0}
          label={labelAccessor(brushEnd ?? 0)}
          height={height}
          dashed={false}
          color={Colors.Background.Field.Primary.Accent}
          focusable
        />
      )}
    </>
  );
}
